// Normaliza lo que manda el formulario y arma el lead que va al sistema.
// Si algo viene mal, tira error y el visitante ve "Reintentar" en vez de un falso OK.

const b = $json.body ?? $json;

const limpio = (v) => String(v ?? '').trim();
const digitos = (v) => String(v ?? '').replace(/\D/g, '');

// Argentina: 54 9 + característica (sin el 0) + número (sin el 15)
function aE164(bruto) {
  let d = digitos(bruto);
  if (!d) return '';
  if (d.startsWith('00')) d = d.slice(2);
  if (d.startsWith('54')) {
    d = d.slice(2);
    if (d.startsWith('9')) d = d.slice(1);
  }
  if (d.startsWith('0')) d = d.slice(1);
  // el 15 va pegado después de la característica (2 a 4 dígitos)
  for (const largo of [2, 3, 4]) {
    if (d.length > largo + 2 && d.slice(largo, largo + 2) === '15') {
      const resto = d.slice(largo + 2);
      if (resto.length >= 6) { d = d.slice(0, largo) + resto; break; }
    }
  }
  return d.length >= 8 ? '549' + d : '';
}

const lead = {
  nombre:        limpio(b.nombre),
  email:         limpio(b.email).toLowerCase(),
  whatsapp:      limpio(b.whatsapp),
  whatsapp_e164: aE164(b.whatsapp),
  rubro:         limpio(b.rubro),
  problema:      limpio(b.problema),

  origen:        limpio(b.origen) || 'web',
  pagina:        limpio(b.pagina),
  utm_source:    limpio(b.utm_source),
  utm_medium:    limpio(b.utm_medium),
  utm_campaign:  limpio(b.utm_campaign),
  utm_content:   limpio(b.utm_content),
  fbclid:        limpio(b.fbclid),
  referrer:      limpio(b.referrer),

  enviado_en:    limpio(b.enviado_en) || new Date().toISOString(),
  recibido_en:   new Date().toISOString()
};

if (!lead.nombre) throw new Error('Falta el nombre');
if (!/^\S+@\S+\.\S+$/.test(lead.email)) throw new Error('Email inválido: ' + lead.email);

return [{ json: lead }];

// El CRM contesta: 201 lead nuevo · 200 ya existia (created:false) · 400 payload
// invalido · 401 token · 500 error del servidor.
// Los 400 y 401 NO se reintentan: van a fallar siempre igual. Por eso el reintento
// ciego de n8n esta apagado; el reintento real lo hace el visitante con el boton.

const r      = $json;
const codigo = Number(r.statusCode);
const cuerpo = r.body ?? {};

if (codigo >= 200 && codigo < 300) {
  return [{ json: { ok: true, codigo, creado: cuerpo.created !== false, lead: cuerpo } }];
}

if (codigo === 400 || codigo === 401) {
  // Esto es un problema NUESTRO, no del visitante. Reintentar no arregla nada.
  // Enganchar acá un aviso (WhatsApp o mail) si querés enterarte en el momento.
  throw new Error('REVISAR EL FLUJO — ' + codigo + ': ' + JSON.stringify(cuerpo));
}

throw new Error('CRM caido — ' + codigo + ': ' + JSON.stringify(cuerpo));
